    if not os.path.exists(ep_file):
        continue
    with open(ep_file) as f:
        for i, line in enumerate(f):
            d = json.loads(line)
            if 'always_internal' not in d:
                print(f'PROBLEM: {task_type} line {i}, keys={list(d.keys())}')
                break
        else:
            continue
        break
    else:
        continue
    break
else:
